CREATE POLICY "Announcement images are readable" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'announcements');
CREATE POLICY "Admins can upload announcement images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'announcements' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can update announcement images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'announcements' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can delete announcement images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'announcements' AND public.has_role(auth.uid(), 'admin'));